class Store:
    def __init__(self, items):
        self.rows = {item.id: item for item in items}

    def add(self, item):
        self.rows[item.id] = item

    def owned(self, owner):
        return sorted((x for x in self.rows.values() if x.owner == owner), key=lambda x: x.id)

